import re

def clean_horse_name(name: str) -> str:
    if not name or not isinstance(name, str):
        return ""
    cleaned = re.sub(r'\(.*?\)', '', name)
    cleaned = cleaned.replace(".", "")
    return " ".join(cleaned.split()).strip().lower()

