def build_broodmare_database():
    """Maps array entries to clean normalization lookups seamlessly."""
    bms_map = {}
    for entry in broodmare_sire_raw:
        norm_key = clean_horse_name(entry["stallion"])
        if norm_key:
            bms_map[norm_key] = {
                "Stallion": entry["stallion"],
                "Rank": entry["rank"],
                "Lineage": entry["lineage"],
                "Dams": str(entry["dams"]),
                "Runners": str(entry["rnrs"]),
                "Winners": str(entry["wnrs"]),
                "Chief Earner": entry["chief_earner"],
                "Chief Earner Earnings": entry["chief_earners_earnings"],
                "2026 Earnings": entry["earnings_2026"],
                "AEI": entry["aei"],
                "Comp Index": entry["comp_index"]
            }
    return bms_map

BROODMARE_DATABASE = build_broodmare_database()